#!/usr/bin/env node
// Stops a "Generated by Claude Code" footer before it reaches GitHub.
//
// The site's people read issue comments in the portal, and Ferst's copy never advertises AI.
// Cloud sessions add that footer by default and an instruction alone didn't stop it, so this
// PreToolUse hook (wired in .claude/settings.json) checks every GitHub write: the command
// text, any body file it posts (`body=@file`, `--body-file file`, `--input file`), and files
// written with the Write tool. Finding the footer, it blocks the call (exit 2) and tells
// Claude why, so the text is fixed and posted again.
import { existsSync, readFileSync } from 'node:fs';
import { isAbsolute, resolve } from 'node:path';

const FOOTER = /Generated (?:by|with) \[Claude Code\]/;
const block = (where) => {
  process.stderr.write(
    `Blocked: ${where} carries a "Generated by Claude Code" footer. The site's people read comments ` +
      'in the portal, and nothing Ferst writes mentions AI. Remove the footer and the --- line above ' +
      'it, then post again.\n',
  );
  process.exit(2);
};

let event;
try {
  event = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  process.exit(0); // not a hook event: nothing to check
}
const input = event?.tool_input ?? {};

if (event?.tool_name === 'Write') {
  if (FOOTER.test(String(input.content ?? ''))) block(`the file ${input.file_path ?? ''}`.trim());
  process.exit(0);
}

const cmd = String(input.command ?? '');
// Only commands that write to GitHub issues, comments or pull requests.
if (!/\bgh\b/.test(cmd) || !/\b(issues?|comments?|pulls?|pr)\b/.test(cmd)) process.exit(0);
if (FOOTER.test(cmd)) block('this command');
for (const m of cmd.matchAll(/(?:body=@|--body-file[= ]|--input[= ])(["']?)([^\s"']+)\1/g)) {
  const path = isAbsolute(m[2]) ? m[2] : resolve(event?.cwd ?? process.cwd(), m[2]);
  if (existsSync(path) && FOOTER.test(readFileSync(path, 'utf8'))) block(`the body in ${m[2]}`);
}
process.exit(0);
